    AV_ENTES.forEach(function(e){ delete window.__ENTES['av-p2|' + e]; });
    ['av-c22', 'av-c22b', 'av-l1', 'av-am1', 'av-am2', 'av-am3'].forEach(function(id){ delete window.__IMPORTE_DOCS[id]; });
