    var x = YPM[k];
    igual(k + ': atrás desde la ' + x.ya + ' vuelve a la ' + x.madre, location.hash, '#tramite-' + x.madre);
    igual(k + ': y a su pregunta, con las dos opciones', yaOpciones(), x.ya + ' ' + x.madre);
